"""EXP-ENGAG-001 review and display-campaign contracts."""
def extend_experience(spec):
    from authorization import object_schema, operation, parameter, UUID, REF, VERSION
    model=spec['components']['schemas'];paths=spec['paths']
    def page(item):return object_schema({'items':{'type':'array','maxItems':100,'items':REF(item)},'page':{'type':'integer','minimum':0},'size':{'type':'integer','minimum':1,'maximum':100},'totalElements':{'type':'integer','format':'int64','minimum':0},'totalPages':{'type':'integer','format':'int64','minimum':0}})
    model['EngagementReviewInput']=object_schema({'kind':{'enum':['PRODUCT','TESTIMONIAL']},'productId':UUID,'orderLineId':UUID,'rating':{'type':'integer','minimum':1,'maximum':5},'title':{'type':'string','maxLength':160},'body':{'type':'string','minLength':1,'maxLength':5000}});model['EngagementReviewInput']['required']=['kind','body'];model['EngagementReviewInput']['allOf']=[{'if':{'properties':{'kind':{'const':'PRODUCT'}},'required':['kind']},'then':{'required':['productId','orderLineId','rating']}},{'if':{'properties':{'kind':{'const':'TESTIMONIAL'}},'required':['kind']},'then':{'not':{'anyOf':[{'required':['productId']},{'required':['orderLineId']}]}}}]
    model['EngagementReview']=object_schema({'id':UUID,'state':{'enum':['PENDING','PUBLISHED','REJECTED','WITHDRAWN']},'rating':{'type':['integer','null'],'minimum':1,'maximum':5},'verifiedPurchase':{'type':'boolean'},'version':VERSION})
    model['EngagementPublicReview']=object_schema({'id':UUID,'displayName':{'type':'string','maxLength':80},'rating':{'type':['integer','null'],'minimum':1,'maximum':5},'title':{'type':['string','null'],'maxLength':160},'body':{'type':'string','maxLength':5000},'verifiedPurchase':{'type':'boolean'},'publishedAt':{'type':'string','format':'date-time'}})
    model['EngagementAdminReview']=object_schema({'id':UUID,'productId':{'anyOf':[UUID,{'type':'null'}]},'orderLineId':{'anyOf':[UUID,{'type':'null'}]},'kind':{'enum':['PRODUCT','TESTIMONIAL']},'title':{'type':['string','null'],'maxLength':160},'body':{'type':'string','maxLength':5000},'rating':{'type':['integer','null'],'minimum':1,'maximum':5},'state':{'enum':['PENDING','PUBLISHED','REJECTED','WITHDRAWN']},'verifiedPurchase':{'type':'boolean'},'version':VERSION})
    model['EngagementModeration']=object_schema({'decision':{'enum':['PUBLISH','REJECT','WITHDRAW']},'reason':{'type':'string','minLength':10,'maxLength':500}})
    model['EngagementCampaignInput']=object_schema({'code':{'type':'string','pattern':'^[A-Z0-9][A-Z0-9_-]{1,79}$'},'title':{'type':'string','minLength':1,'maxLength':180},'marketId':UUID,'commercialRuleId':UUID,'displayConfig':{'type':'object','maxProperties':7,'additionalProperties':{'type':'string','maxLength':500}},'startsAt':{'type':'string','format':'date-time'},'endsAt':{'type':'string','format':'date-time'},'published':{'type':'boolean'}});model['EngagementCampaignInput']['required']=['code','title','marketId','displayConfig','startsAt','endsAt','published']
    model['EngagementCampaign']=object_schema({'id':UUID,'code':{'type':'string','maxLength':80},'title':{'type':'string','maxLength':180},'marketId':UUID,'commercialRuleId':{'anyOf':[UUID,{'type':'null'}]},'displayConfig':{'type':'object'},'startsAt':{'type':'string','format':'date-time'},'endsAt':{'type':'string','format':'date-time'},'published':{'type':'boolean'},'version':VERSION})
    model['EngagementPublicCampaign']=object_schema({'id':UUID,'code':{'type':'string','maxLength':80},'title':{'type':'string','maxLength':180},'displayConfig':{'type':'object'},'startsAt':{'type':'string','format':'date-time'},'endsAt':{'type':'string','format':'date-time'}})
    model['EngagementReviewPage']=page('EngagementPublicReview');model['EngagementAdminReviewPage']=page('EngagementAdminReview')
    no_store={'Cache-Control':{'schema':{'const':'no-store'}}}
    def command(api,description,response,path,body,status=200,params=(),scope=None):
        op=operation(api,description,response,list(params));op['responses'][str(status)]=op['responses'].pop('200');op['responses'][str(status)].setdefault('headers',{}).update(no_store);op['requestBody']={'required':True,'content':{'application/json':{'schema':REF(body)}}}
        if scope:op['security']=[{'workload':[scope],'signedActor':[]}]
        paths[path]={'post':op};return op
    key=parameter('Idempotency-Key','header',{'type':'string','minLength':1,'maxLength':100,'pattern':r'^[ -~]+$'},True)
    create=command('API-096','Current signed Commerce CUSTOMER. PRODUCT reviews require a purchase proof through Commerce API-121; caller cannot set verifiedPurchase. Proof is checked before the Experience write transaction. New reviews are always PENDING.','EngagementReview','/api/v1/reviews','EngagementReviewInput',201,[key],'reviews.create_WITH_SIGNED_CUSTOMER');create['responses']['422']={'description':'Purchase proof rejected','content':{'application/problem+json':{'schema':{'$ref':'../problem/problem.schema.json'}}}}
    public=operation('API-097','Public, published-only; no email, party ID or private order data. displayName is a fixed generic label until consented alias input and schema are available.','EngagementReviewPage',[parameter('productId','query',UUID),parameter('kind','query',{'enum':['PRODUCT','TESTIMONIAL']}),parameter('page','query',{'type':'integer','minimum':0,'default':0}),parameter('size','query',{'type':'integer','minimum':1,'maximum':100,'default':20}),parameter('sort','query',{'enum':['publishedAt,desc','publishedAt,asc'],'default':'publishedAt,desc'})]);public['security']=[];paths['/api/v1/reviews']={'get':public}
    moderation=command('API-098','Current signed CONTENT_PUBLISHER; If-Match revision and Idempotency-Key required. Sanitized moderation reason is audited; publication commits EVT-021 in the same Experience transaction.','EngagementReview','/api/v1/staff/reviews/{id}/moderation','EngagementModeration',200,[parameter('id','path',UUID,True),parameter('If-Match','header',{'type':'string','pattern':'^"(0|[1-9][0-9]{0,18})"$'},True),key],'reviews.moderate_WITH_SIGNED_ACTOR');moderation['responses']['200']['headers']['ETag']={'schema':{'type':'string'}}
    queue=operation('API-176','Current signed CONTENT_PUBLISHER only. Private moderation queue excludes party identity, email and order data.','EngagementAdminReviewPage',[parameter('state','query',{'enum':['PENDING','PUBLISHED','REJECTED','WITHDRAWN']}),parameter('kind','query',{'enum':['PRODUCT','TESTIMONIAL']}),parameter('page','query',{'type':'integer','minimum':0,'default':0}),parameter('size','query',{'type':'integer','minimum':1,'maximum':100,'default':20}),parameter('sort','query',{'enum':['createdAt,asc','createdAt,desc'],'default':'createdAt,desc'})]);queue['security']=[{'workload':['reviews.read_WITH_SIGNED_ACTOR'],'signedActor':[]}];paths['/api/v1/staff/reviews']={'get':queue}
    command('API-108','Current signed SALES. Only closed display configuration is stored. The market is checked against Commerce API-029. A commercialRuleId is rejected until Commerce exposes a safe validation API; a display campaign never grants discount or entitlement.','EngagementCampaign','/api/v1/staff/campaigns','EngagementCampaignInput',201,[key],'campaigns.write_WITH_SIGNED_ACTOR')
    campaigns=operation('API-109','Public published active campaigns for a required market.','EngagementPublicCampaign',[parameter('market','query',{'type':'string','pattern':'^[A-Z0-9][A-Z0-9_-]{1,39}$'},True)]);campaigns['security']=[];campaigns['responses']['200']['content']['application/json']['schema']={'type':'array','maxItems':100,'items':REF('EngagementPublicCampaign')};paths['/api/v1/campaigns']={'get':campaigns}
    spec['components']['securitySchemes']['signedActor']={'type':'apiKey','in':'header','name':'X-Nigson-Actor'}
    spec['components']['securitySchemes']['workload']['flows']['clientCredentials']['scopes'].update({'reviews.create_WITH_SIGNED_CUSTOMER':'Create a customer review','reviews.moderate_WITH_SIGNED_ACTOR':'Moderate reviews','reviews.read_WITH_SIGNED_ACTOR':'Read private review queue','campaigns.write_WITH_SIGNED_ACTOR':'Create display campaigns'})
    return spec
